111	async function adminReviewSource(c:any,actionValue:'approve'|'reject',providedInput?:any){
112	  const listingId=c.req.param('id'),input=actionValue==='reject'?(providedInput??await c.req.json().catch(()=>null)):null;
113	  const reason=actionValue==='reject'&&typeof input?.reason==='string'?input.reason.trim():null;
114	  if(actionValue==='reject'&&(reason===null||reason.length<3||reason.length>1000))return c.json({error:'rejection reason must contain 3 to 1000 non-blank characters'},400);
115	  const current=await c.env.DB.prepare('SELECT l.status,l.publication_status AS publicationStatus,l.rejection_reason AS rejectionReason,u.role AS ownerRole,EXISTS(SELECT 1 FROM listing_images i WHERE i.listing_id=l.id AND i.blob_data IS NULL) AS hasLegacyMedia FROM listings l JOIN users u ON u.id=l.owner_id WHERE l.id=?').bind(listingId).first() as any;
116	  if(!current||current.ownerRole!=='OWNER')return c.json({message:'Listing not found'},404);
117	  if(actionValue==='approve'&&d1ImageStatus(c)&&current.hasLegacyMedia)return legacyD1Conflict(c);
118	  const at=now(),eventId=id(),action=actionValue==='approve'?'ADMIN_LISTING_APPROVED':'ADMIN_LISTING_REJECTED',status=actionValue==='approve'?'APPROVED':'REJECTED';
119	  if((actionValue==='approve'&&current.status==='APPROVED')||(actionValue==='reject'&&current.status==='REJECTED'&&current.rejectionReason===reason)){
120	    const conditions=actionValue==='approve'?"l.status='APPROVED'":"l.status='REJECTED' AND l.rejection_reason=?",args=actionValue==='approve'?[]:[reason];
121	    try{const results=await c.env.DB.batch([sourceAuditInsert(c,eventId,listingId,action,reason,at,`l.id=? AND owner.role='OWNER' AND ${conditions}`,[listingId,...args])]);if(results[0]?.meta?.changes!==1)return c.json({error:'listing changed during review'},409);}
122	    catch{return c.json({error:'review outcome could not be confirmed'},503);}
123	    const result=await sourceAdminListing(c.env.DB,listingId,c.env.MEDIA_STRATEGY);return result?c.json(result):c.json({message:'Listing not found'},404);
124	  }
