266	async function uploadD1Image(c:any,lid:string){
267	  if(!await owned(c,lid))return c.json({error:'not found'},404);
268	  const key=requestKey(c);if(!key)return c.json({error:'Idempotency-Key required for image upload'},400);
269	  const rawLength=c.req.header('content-length');
270	  if(rawLength!==undefined&&(!/^\d+$/.test(rawLength)||Number(rawLength)>D1_IMAGE_MAX_BYTES))return c.json({error:'image exceeds the 1.8 MB limit'},413);
271	  const originalName=cleanImageName(c.req.header('x-image-name'));
272	  const type=c.req.header('content-type')??'';
273	  if(!originalName)return c.json({error:'invalid image name'},400);
274	  const bytes=await readBoundedBody(c.req.raw);
275	  if(!bytes)return c.json({error:'image exceeds the 1.8 MB limit or has no body'},413);
276	  if(rawLength!==undefined&&Number(rawLength)!==bytes.byteLength)return c.json({error:'content length does not match image bytes'},400);
277	  if(!await validateImageBytes(bytes,type))return c.json({error:'unsupported or invalid JPEG, PNG, or WebP image'},400);
278	  const owner=ownerId(c),scope=`IMAGE_ADD:${lid}`,contentHash=b64(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes.slice().buffer as ArrayBuffer)));
279	  const requestFingerprint=await fingerprint({listingId:lid,name:originalName,type,size:bytes.byteLength,contentHash});
280	  const lease=await lock(c.env.DB,lid);if(!lease)return c.json({error:'listing is busy; retry with the same idempotency key'},409);
281	  try{
282	    if(!await owned(c,lid))return c.json({error:'not found'},404);
283	    if(await hasLegacyD1Images(c.env.DB,lid))return legacyD1Conflict(c);
284	    let record:any;
285	    try{record=await c.env.DB.prepare('SELECT request_fingerprint,state,result_json FROM idempotency_records WHERE owner_id=? AND scope=? AND request_key=?').bind(owner,scope,key).first();}catch{return c.json({error:'image request outcome unavailable; retry with the same idempotency key'},503);}
286	    if(record){
287	      if(record.request_fingerprint!==requestFingerprint)return c.json({error:'idempotency key reused with different image'},409);
288	      if(record.state!=='COMMITTED'||typeof record.result_json!=='string')return c.json({error:'image reservation requires recovery; retry with the same idempotency key'},503);
289	      try{return c.json(JSON.parse(record.result_json),201);}catch{return c.json({error:'image replay result is invalid'},503);}
290	    }
291	    const staticImage=await c.env.DB.prepare('SELECT 1 FROM static_listing_images WHERE listing_id=? LIMIT 1').bind(lid).first();
292	    if(staticImage)return c.json({error:'listing uses repository-managed images'},409);
293	    const images=await orderedD1Images(c.env.DB,lid);
294	    if(!images.every((row,index)=>row.position===index))return c.json({error:'image order requires recovery'},503);
295	    if(images.length>=D1_IMAGE_MAX_COUNT)return c.json({error:'listing image limit reached'},409);
296	    const usage=await c.env.DB.prepare('SELECT used_bytes FROM media_storage_usage WHERE id=1').first() as {used_bytes:number}|null;
297	    if(!usage)return c.json({error:'image storage unavailable'},503);
298	    if(usage.used_bytes+bytes.byteLength>D1_MEDIA_QUOTA_BYTES)return c.json({error:'Preview image storage quota reached'},507);
299	    const imageId=id(),created=now(),objectKey=`d1blob:${imageId}`;
300	    const body={id:imageId,originalName,contentType:type,sizeBytes:bytes.byteLength,position:images.length,createdAt:created};
301	    const binary=bytes.slice().buffer as ArrayBuffer;
302	    try{
303	      const results=await c.env.DB.batch([
304	        c.env.DB.prepare('INSERT INTO listing_images(id,listing_id,object_key,original_name,mime_type,byte_size,position,created_at,updated_at,blob_data) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(imageId,lid,objectKey,originalName,type,bytes.byteLength,images.length,created,created,binary),
305	        c.env.DB.prepare("INSERT INTO idempotency_records(owner_id,scope,request_key,request_fingerprint,resource_id,state,result_json,created_at,updated_at) VALUES(?,?,?,?,?,'COMMITTED',?,?,?)").bind(owner,scope,key,requestFingerprint,imageId,JSON.stringify(body),created,created),
306	      ]);
307	      const batchResults=results as D1Result[];if(batchResults.length!==2||batchResults.some(result=>result.meta?.changes!==1))throw new Error('image batch not confirmed');
308	    }catch{
309	      try{record=await c.env.DB.prepare('SELECT request_fingerprint,state,result_json FROM idempotency_records WHERE owner_id=? AND scope=? AND request_key=?').bind(owner,scope,key).first();}catch{return c.json({error:'image commit outcome unknown; retry with the same idempotency key'},503);}
310	      if(record?.request_fingerprint===requestFingerprint&&record.state==='COMMITTED'&&typeof record.result_json==='string')return c.json(JSON.parse(record.result_json),201);
311	      const after=await c.env.DB.prepare('SELECT used_bytes FROM media_storage_usage WHERE id=1').first().catch(()=>null) as {used_bytes:number}|null;
312	      if(after&&after.used_bytes+bytes.byteLength>D1_MEDIA_QUOTA_BYTES)return c.json({error:'Preview image storage quota reached'},507);
313	      return c.json({error:'image was not committed; retry with the same idempotency key'},503);
314	    }
315	    return c.json(body,201);
316	  }finally{await unlock(c.env.DB,lid,lease);}
